def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None
    roi = (new - old) / old * 100
    return {
        "value": roi,
        "trace": {
            "old_value": old,
            "new_value": new,
            "change_ratio": (new - old) / old,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
